    `})},le={name:"Notice — Declined",render:()=>({components:{DocumentViewerShell:ae},setup(){return{DOCUMENT:te,RECIPIENTS:de,notice:{variant:"error",text:"This contract was declined. Please contact the sender for next steps."}}},template:`
      <DocumentViewerShell
